'use strict';
const ReceiptAlerts={value:null,timer:null,busy:false,
 async refresh(){if(!Business.can('receipt:review')||this.busy)return;this.busy=true;try{this.value=await API.request('/receipts/summary');for(const a of document.querySelectorAll('[data-primary-route="receipts"]')){a.querySelector('.approval-badge')?.remove();if(this.value.pending){const badge=document.createElement('span');badge.className='approval-badge';badge.textContent=String(this.value.pending);badge.setAttribute('aria-label',this.value.pending+'张待审批入库单');badge.title='筛选待审批入库单';badge.onclick=e=>{e.preventDefault();e.stopPropagation();Router.go('/receipts?status=PENDING');};a.append(badge);}}return this.value;}catch(e){for(const a of document.querySelectorAll('[data-primary-route="receipts"]')){const badge=a.querySelector('.approval-badge');if(badge){badge.textContent='!';badge.title='待审批数量加载失败，请重新查询';}}}finally{this.busy=false;}},
 async start(){if(!Business.can('receipt:review'))return;await this.refresh();window.addEventListener('inventory-changed',()=>{clearTimeout(this.timer);this.timer=setTimeout(()=>this.refresh(),120);});window.addEventListener('focus',()=>this.refresh());document.addEventListener('visibilitychange',()=>{if(!document.hidden)this.refresh();});this.interval=setInterval(()=>{if(!document.hidden&&window.AppSignedIn)this.refresh();},60000);}
};
Business.statuses={DRAFT:'草稿',PENDING:'待审批',CONFIRMED:'已审批',REJECTED:'已驳回'};
Business.receipts=async function(){let current=new URLSearchParams(location.search).get('status')||'',sequence=0;const labels=this.statuses;
 this.open('入库管理',`<p class="page-intro">生产入库、审核与片数登记。审核确认后进入可备货库存。</p><div class="approval-cards" id="receipt-approval-cards" aria-label="入库审批统计"></div><div class="business-toolbar">${this.can('receipt:write')?'<a class="button primary" href="/receipts/new">新建入库单</a><a class="button secondary" href="/receipts/import">Excel批量导入</a>':''}<label>单据状态<select id="receipt-status"><option value="">全部状态</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><span class="quiet-note">优先展示待审批，当前筛选最近200张</span></div><p class="error" id="receipt-list-error" role="alert"></p><div id="receipt-list" aria-live="polite"></div>`);
 const load=async status=>{const seq=++sequence,listNode=$('receipt-list');current=status;const url=new URL(location.href);if(status)url.searchParams.set('status',status);else url.searchParams.delete('status');history.replaceState({},'',url.pathname+url.search);$('receipt-status').value=status;$('receipt-list-error').textContent='';try{const [r,s]=await Promise.all([API.request('/receipts'+(status?'?status='+status:'')),this.can('receipt:review')?API.request('/receipts/summary'):Promise.resolve(null)]);if(seq!==sequence||!listNode.isConnected)return;ReceiptAlerts.value=s;$('receipt-approval-cards').hidden=!s;$('receipt-approval-cards').innerHTML=s?[['PENDING','待审批',s.pending],['CONFIRMED','已审批通过',s.confirmed],['REJECTED','已驳回',s.rejected]].map(([key,label,count])=>`<button type="button" class="approval-card ${key==='PENDING'?'attention':''} ${status===key?'selected':''}" data-receipt-filter="${key}"><span>${label}</span><strong>${count}</strong><small>查看单据 →</small></button>`).join(''):'';$('receipt-list').innerHTML='<div class="business-table"><table><thead><tr><th>入库单号</th><th>客户</th><th>状态</th><th class="numeric">捆数</th><th>创建人</th><th>操作</th></tr></thead><tbody>'+r.items.map(d=>`<tr class="${d.status==='PENDING'?'approval-pending-row':''}"><td>${esc(d.code)}</td><td>${esc(d.customer_name)}</td><td><span class="status-pill status-${d.status.toLowerCase()}">${labels[d.status]}</span></td><td class="numeric">${d.line_count}</td><td>${esc(d.creator_name)}</td><td><a class="button secondary compact" href="/receipts/${d.id}">${d.status==='PENDING'&&this.can('receipt:review')?'查看 / 审核':'查看详情'}</a></td></tr>`).join('')+(r.items.length?'':'<tr><td colspan="6" class="empty">当前状态没有授权入库单</td></tr>')+'</tbody></table></div>';for(const b of document.querySelectorAll('[data-receipt-filter]'))b.onclick=()=>load(b.dataset.receiptFilter);await ReceiptAlerts.refresh();}catch(e){if(seq!==sequence||!listNode.isConnected)return;$('receipt-list-error').textContent=e.message;$('receipt-list').replaceChildren();}};
 $('receipt-status').onchange=e=>load(e.target.value);await load(current);
};
V261.states.CANCELLED='已撤销';V262.locationNames.PUBLIC_TEMPORARY='公共临时堆存区';
const supplementLotDetail=V262.detail.bind(V262);
V262.detail=async function(id){if(location.pathname!=='/preparation/'+id)return;await supplementLotDetail(id);if(location.pathname!=='/preparation/'+id||!$('v262-summary'))return;const summaryNode=$('v262-summary'),a=await API.request('/v261/lots/'+id),p=a.preapproval;if(location.pathname!=='/preparation/'+id||!summaryNode.isConnected||summaryNode!==$('v262-summary')||!p)return;$('v261-cancel')?.remove();const area=document.createElement('div');area.className='business-toolbar preapproval-actions';area.innerHTML=`${p.can_withdraw?'<button type="button" class="button secondary" id="lot-withdraw">撤回审核</button>':''}${p.can_revoke?'<button type="button" class="button danger-outline" id="lot-revoke">撤销备货</button>':''}${p.blocked_reason?'<span class="quiet-note">'+esc(p.blocked_reason)+'</span>':''}`;$('v262-history').before(area);
 const popup=document.createElement('dialog');popup.id='lot-preapproval-dialog';popup.className='product-dialog';popup.innerHTML=`<form id="lot-preapproval-form"><header><h2 id="lot-preapproval-title"></h2><p>Lot ${esc(a.lot_no)} · ${esc(V261.states[a.workflow_state])}</p></header><dl class="confirmation-grid" id="lot-preapproval-facts"><dt>销售计划</dt><dd>${esc(a.plan.code)}</dd><dt>当前分配客户</dt><dd>${esc(a.plan.customer_name)}</dd><dt>原始备货捆数</dt><dd>${a.quantities?.original_count??a.summary.total}</dd><dt>已检斤 / 已取样</dt><dd>${a.summary.weighed} / ${a.items.filter(b=>['RETURNED','WEIGHED'].includes(b.sample_stage)).length} 捆</dd><dt>规划堆存货位</dt><dd>${esc(a.planned.code)}</dd></dl><div id="lot-revoke-fields"><p class="work-notice" id="lot-preapproval-work-notice">${p.has_operations?'已存在检斤、取样、铅封或移位记录，撤销后全部保留。':''}不会自动移动捆包；货位仍有实物或业务占用时继续保留锁定。</p>${p.blocked_reason?'<p class="error">'+esc(p.blocked_reason)+'</p>':''}<label><span>撤销原因 <span class="required-mark">*</span></span><textarea name="reason" maxlength="1000" rows="2"></textarea></label><label class="check-label"><input type="checkbox" name="work_stopped">已停止原备货作业</label><label class="check-label"><input type="checkbox" name="physical_state_verified">已逐捆核实当前实物位置</label><label><span>现场作业及位置核实说明${p.has_operations?' <span class="required-mark">*</span>':''}</span><textarea name="observation" maxlength="1000" rows="2"></textarea></label></div><p id="lot-withdraw-note" class="work-notice">撤回后恢复备货作业中，保留检斤、铅封与取样状态，捆包及规划货位继续锁定。</p><p id="lot-preapproval-error" class="error" role="alert"></p><footer><button type="button" id="lot-preapproval-back" class="button secondary">返回</button><button class="button primary" id="lot-preapproval-confirm">确认</button></footer></form>`;$('page-content').append(popup);let action,current=a,policy=p;
 const open=async kind=>{try{current=await API.request('/v261/lots/'+id);policy=current.preapproval;if(!(kind==='withdraw'?policy?.can_withdraw:policy?.can_revoke)){notify('Lot状态或权限已变化，请刷新核对最新记录');return;}$('lot-preapproval-facts').innerHTML='<dt>销售计划</dt><dd>'+esc(current.plan.code)+'</dd><dt>当前分配客户</dt><dd>'+esc(current.plan.customer_name)+'</dd><dt>原始备货捆数</dt><dd>'+(current.quantities?.original_count??current.summary.total)+'</dd><dt>已检斤 / 已取样</dt><dd>'+current.summary.weighed+' / '+current.items.filter(b=>['RETURNED','WEIGHED'].includes(b.sample_stage)).length+' 捆</dd><dt>规划堆存货位</dt><dd>'+esc(current.planned.code)+'</dd>';$('lot-preapproval-work-notice').textContent=(policy.has_operations?'已存在检斤、取样、铅封或移位记录，撤销后全部保留。':'')+'不会自动移动捆包；货位仍有实物或业务占用时继续锁定。';}catch(e){notify(e.message);return;}action=kind;$('lot-preapproval-title').textContent=kind==='withdraw'?'撤回备货审核':'撤销备货';$('lot-revoke-fields').hidden=kind!=='revoke';$('lot-withdraw-note').hidden=kind!=='withdraw';const form=$('lot-preapproval-form');form.elements.reason.required=kind==='revoke';form.elements.work_stopped.required=kind==='revoke';form.elements.physical_state_verified.required=kind==='revoke';form.elements.observation.required=kind==='revoke'&&policy.has_operations;$('lot-preapproval-error').textContent='';$('lot-preapproval-confirm').textContent=kind==='withdraw'?'确认撤回':'确认撤销';$('lot-preapproval-confirm').className='button '+(kind==='withdraw'?'primary':'danger');popup.showModal();};if($('lot-withdraw'))$('lot-withdraw').onclick=()=>open('withdraw');if($('lot-revoke'))$('lot-revoke').onclick=()=>open('revoke');$('lot-preapproval-back').onclick=()=>popup.close();$('lot-preapproval-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const form=e.target;try{await API.request('/v262/lots/'+id+'/'+action,{method:'POST',body:{version:current.version,reason:form.elements.reason.value,observation:form.elements.observation.value,work_stopped:form.elements.work_stopped.checked,physical_state_verified:form.elements.physical_state_verified.checked}});popup.close();notify(action==='withdraw'?'已撤回审核，捆包及货位继续锁定':'备货已撤销，历史记录保留');await this.detail(id);}catch(err){if(popup.isConnected){popup.querySelector('#lot-preapproval-error').textContent=err.message;e.submitter.disabled=false;}else notify('请核对操作结果：'+err.message);}};
};
V261.detail=V262.detail.bind(V262);Business.allocationDetail=V261.detail;
StockMap.stateNames.TEMPORARY='公共临时堆存区';
const supplementMapDraw=StockMap.draw.bind(StockMap),supplementMapSelect=StockMap.select.bind(StockMap);
StockMap.draw=function(){supplementMapDraw();const cell=document.querySelector('[data-map-cell="P5"]');if(cell){cell.classList.add('map-public-p5');cell.setAttribute('data-i18n','');cell.setAttribute('aria-label','P5 临时堆存区');const title=cell.querySelector('title');if(title)title.textContent='P5 公共临时堆存区，可共存多个入库批次；实物数量按数据库统计';if(cell.namespaceURI.includes('svg')){const texts=cell.querySelectorAll('text');if(texts[0])texts[0].textContent='P5';if(texts[1]){texts[1].textContent='临时堆存区';texts[1].setAttribute('x',Number(this.data.cells.find(c=>c.code==='P5').x)+100);}}}};
StockMap.unmapped=function(){const hidden=this.data.occupancy.unmapped_locations;$('stock-map-unmapped').innerHTML=hidden?'<p class="quiet-note">未定位或无效的历史货位已从现场图和新Lot正式货位选择中隐藏；相关库存与历史保留，可在库存查询中核查。'+(this.data.review_summary?.bundle_count?'其中仓库授权范围待核查实物 '+this.data.review_summary.bundle_count+' 捆，已包含在仓库总量，未虚构地图位置。':'')+'</p>':'';};
StockMap.select=async function(id,page=1){const loc=this.data.locations.find(l=>l.id===id);if(loc?.map_usage!=='TEMPORARY')return supplementMapSelect(id,page);const seq=++this.detailSequence,area=$('stock-map-detail');area.innerHTML='<p role="status">正在读取P5临时堆存区…</p>';try{const q=this.params();q.set('page',page);const r=await API.request('/stock-map/locations/'+id+'?'+q);if(seq!==this.detailSequence)return;const s=r.summary,knownGross=s.bundle_count&&s.missing_gross_count===s.bundle_count?'未知':Tonnes.format(s.known_gross_weight),knownNet=s.bundle_count&&s.unweighed_count===s.bundle_count?'未知':Tonnes.format(s.known_net_weight);area.innerHTML=`<h2 data-i18n>P5 临时堆存区</h2><p class="quiet-note">公共区域，不参与单Lot独占</p><dl><dt>当前实物捆数</dt><dd>${s.bundle_count}</dd><dt>总片数</dt><dd>${s.total_sheets??'未录入'}${s.missing_sheets_count?'（'+s.missing_sheets_count+'捆未录入）':''}</dd><dt>尚未检斤</dt><dd>${s.unweighed_count||0} 捆</dd><dt>已知毛重 / 净重(t)</dt><dd>${knownGross} / ${knownNet}</dd><dt>已锁定 / 可用</dt><dd>${s.locked_count} / ${s.available_count} 捆</dd></dl><p class="work-notice">创建Lot时实物可留在P5；主管审核并确认归位后才更新正式货位。未知重量不推算。</p><a class="button secondary" href="/inventory?location=${encodeURIComponent('临时堆存区')}">查看临时区库存</a><div class="map-detail-table"><table><thead><tr><th>捆包编号</th><th class="numeric">片数</th><th class="numeric">毛重 / 净重(t)</th><th>状态</th></tr></thead><tbody>${r.items.map(b=>`<tr><td><a href="/inventory/${encodeURIComponent(b.id)}">${esc(b.id)}</a></td><td class="numeric">${b.sheets_per_bundle??'未录入'}</td><td class="numeric">${Tonnes.format(b.gross_weight)} / ${Tonnes.format(b.weight)}</td><td>${esc(b.status)} · ${esc(b.sample)}</td></tr>`).join('')||'<tr><td colspan="4">当前筛选无实物库存</td></tr>'}</tbody></table></div><div class="business-toolbar"><button type="button" id="p5-prev" class="button secondary" ${page===1?'disabled':''}>上一页</button><span>${page} / ${Math.max(1,Math.ceil(r.total/20))}</span><button type="button" id="p5-next" class="button secondary" ${page*20>=r.total?'disabled':''}>下一页</button></div>`;$('p5-prev').onclick=()=>this.select(id,page-1);$('p5-next').onclick=()=>this.select(id,page+1);const u=new URL(location.href);u.searchParams.set('focus',id);history.replaceState({},'',u.pathname+u.search);}catch(e){if(seq===this.detailSequence)area.innerHTML='<p class="error" role="alert">'+esc(e.message)+'</p>';}};

const supplementMapRegion=StockMap.region.bind(StockMap);StockMap.region=function(code){if(code!=='P5')return supplementMapRegion(code);const p5=this.data.locations.find(l=>l.map_usage==='TEMPORARY');if(p5){this.viewRegion='P5';this.zoom=1;this.draw();this.select(p5.id);}};
